        public override PacketStream Write(PacketStream stream)
        {
            stream.Write(_division);
            stream.Write(_type);
            stream.Write((short)_msg.Length); // len
            stream.Write((short)_msg.Length); // len
            stream.Write(_msg.Length - 4);        // len
            stream.Write((byte)2);
            stream.Write(_count);
            stream.Write(_msg, false);

            return stream;
        }

        private void SetMessageFromHexString(string hexString)
        {
            // Удаляем все пробелы
            var cleanedHexString = hexString.Replace(" ", "");
    
            // Проверяем, что строка имеет четную длину
            if (cleanedHexString.Length % 2 != 0)
            {
                throw new ArgumentException("Hex string must have an even number of characters");
            }
    
            // Вычисляем количество байтов (2 символа на байт)
            var byteCount = cleanedHexString.Length / 2;
    
            // Создаем массив точного размера
            _msg = new byte[byteCount + 10];
    
            // Заполняем массив
            for (var i = 0; i < byteCount; i++)
            {
                var byteValue = cleanedHexString.Substring(i * 2, 2);
                _msg[i] = Convert.ToByte(byteValue, 16);
            }
        }
